_DISTRICT_BY_KEY: dict[str, dict[str, Any]] = {}
for _d in AZ_DISTRICTS:
    _DISTRICT_BY_KEY[_d["id"].lower()] = _d
    _DISTRICT_BY_KEY[_d["name_en"].lower()] = _d
    _DISTRICT_BY_KEY[_d["name_az"].lower()] = _d


def find_az_district(query: str | None) -> dict[str, Any] | None:
    if not query:
        return None
    key = query.strip().lower().removeprefix("az-")
    if key in _DISTRICT_BY_KEY:
        return _DISTRICT_BY_KEY[key]
    for name_key, record in _DISTRICT_BY_KEY.items():
        if len(name_key) >= 4 and name_key in key:
            return record
    return None
